def oracle_end_periods(dates, end_months, dt_type):
    """Right-closed period-end resample: label for date d = latest period end >= d."""
    labels = []
    for d in dates:
        # candidate: find smallest end-month in cycle whose month-end >= d
        for k in range(4):
            m = end_months[k % len(end_months)]
            y = d.year + (1 if m < d.month else 0)
