def key(d): return (d.year, d.month, d.day, d.hour, d.minute, d.second, d.microsecond)

def total_seconds(d):
    # total seconds since 0000-01-01 using day counts (calendar dependent but consistent)
    ref = d.replace(year=0, month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
    return (d - ref)

def tick_oracle(dates, freq_td, origin_mode, offset_td):
    """Compute labels per xarray/pandas tick resample semantics (left-closed default)."""
    first, last = dates[0], dates[-1]
    if origin_mode == "start_day":
        origin = first.replace(hour=0, minute=0, second=0, microsecond=0)
    elif origin_mode == "start":
        origin = first
    elif origin_mode == "epoch":
        origin = cftime.DatetimeGregorian(1970, 1, 1)
    elif origin_mode == "end":
        origin = last
    elif origin_mode == "end_day":
        # ceiling midnight of last day
        origin = last.replace(hour=0, minute=0, second=0, microsecond=0)
        if key(last) > key(origin):
            origin = origin + datetime.timedelta(days=1)
    if offset_td: origin = origin + offset_td
    def mod_seconds(dt):
        return (dt - origin)  # timedelta
    foff = mod_seconds(first); loff = mod_seconds(last)
    # closed=left, label=left
    f = first - foff if foff.total_seconds() > 0 else first
    l = last + (freq_td - loff) if loff.total_seconds() > 0 else last + freq_td
    # bins: f, f+freq, ..., >= l
    out = [f]
    while out[-1] < l:
        out.append(out[-1] + freq_td)
    # labels = bin starts (label=left)
    return out[1:-1]

def label_by_bin(d, bins):
    # left-closed: label = largest bin_start <= d
    best = None
    for b in bins:
        if key(b) <= key(d):
            best = b
        else:
